-- 식사를 고르면 밥·면 중 하나를 더 고를 수 있게 해요(사용자 11-02). 고기·술안주·분식처럼 어느 쪽도 아닌 메뉴는 비워 두고 '전체'에서만 나와요.
alter table public.menus add column staple text check (staple in ('밥', '면'));

update public.menus set staple = '밥' where name in ('김치찌개', '된장찌개', '순두부찌개', '부대찌개', '제육볶음', '비빔밥', '국밥', '순대국', '설렁탕', '해장국', '육개장', '갈비탕', '김밥', '백반', '알밥', '불고기', '쌈밥', '김치찜', '곰탕', '삼계탕', '추어탕', '닭볶음탕', '찜닭', '감자탕', '낙지볶음', '쭈꾸미볶음', '생선구이', '청국장', '동태찌개', '전복죽', '한정식', '떡갈비', '도시락', '주먹밥', '보리밥', '코다리찜', '갈치조림', '간장게장', '오징어볶음', '볶음밥', '마파두부', '잡채밥', '돈카츠', '초밥', '규동', '텐동', '규카츠', '연어덮밥', '가츠동', '오야코동', '카이센동', '장어덮밥', '리조또', '오므라이스', '포케', '커리', '나시고랭', '카오팟', '푸팟퐁커리', '콩나물국밥', '대구탕', '도가니탕', '굴국밥', '닭곰탕', '갈비찜');
update public.menus set staple = '면' where name in ('냉면', '칼국수', '콩국수', '막국수', '잔치국수', '수제비', '라면', '쫄면', '장칼국수', '짜장면', '짬뽕', '우육면', '울면', '라멘', '우동', '소바', '파스타', '쌀국수', '분짜', '팟타이', '분보후에', '라자냐');
